// Worker entry: OpenNext's Next.js handler, plus a Cron Trigger that starts the daily BrickLink sync.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import handler from '../.open-next/worker.js';

type Env = { CRON_SECRET?: string };

const worker = {
  fetch: handler.fetch,

  async scheduled(_event: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    if (!env.CRON_SECRET) return console.error('Set the CRON_SECRET secret to enable the scheduled sync.');
    const req = new Request('https://cron.internal/api/v1/sync', { method: 'POST', headers: { Authorization: `Bearer ${env.CRON_SECRET}` } });
    ctx.waitUntil(handler.fetch(req, env, ctx).then(async (r: Response) => console.log('scheduled sync:', r.status, await r.text())));
  },
};

export default worker;
